async def execute(document_id=None, law_id=None, max_chars=None, offset=None):
    """Read one document.law row as text, reporting truncation."""
    if 'document.law' not in env:
        return json.dumps({
            'error': 'document.law is not installed',
            'retryable': False,
        })
    law = _find_law(document_id, law_id)
    if not law:
        return json.dumps({
            'error': 'No law matches the given identifier',
            'parameter': 'document_id' if document_id else 'law_id',
            'expected': 'a rss_dok_id or Odoo record id of an existing law',
            'actual': str(document_id or law_id),
            'retryable': False,
        })

    max_chars = max(1, _to_int(max_chars, 8000))
    offset = max(0, _to_int(offset, 0))

    text = law.rss_text or ''
    if not text and law.rss_html:
        text = env['ai.okf.mixin']._okf_html_to_text(law.rss_html)
    text = text or ''
    total_chars = len(text)
    chunk = text[offset:offset + max_chars]
    returned_to = offset + len(chunk)
    truncated = returned_to < total_chars

    out = {
        'id': law.id,
        'document_id': law.rss_dok_id or None,
        'designation': law.rss_beteckning or None,
        'title': law.rss_titel or None,
        'subtitle': law.rss_subtitel or None,
        'department': law.rss_organ or None,
        'date': str(law.rss_datum) if law.rss_datum else None,
        'published': str(law.rss_publicerad) if law.rss_publicerad else None,
        'text': chunk,
        'text_chars': total_chars,
        'truncated': truncated,
    }
    if truncated:
        out['message'] = (
            'Text truncated: showing characters %d-%d of %d. Call law_get '
            'again with offset=%d to read the remainder.'
            % (offset, returned_to, total_chars, returned_to))
    return json.dumps(out, ensure_ascii=False, default=str)


def _to_int(value, default):
    """Parse `value` as an int, or return `default` (sandbox-safe)."""
    if value is None or value is False:
        return default
    text = str(value).strip()
    if not text:
        return default
    negative = text.startswith('-')
    digits = text[1:] if negative else text
    if not digits.isdigit():
        return default
    number = int(digits)
    return -number if negative else number


def _find_law(document_id=None, law_id=None):
    """Find one document.law by record id or document id. Empty if none."""
    Law = env['document.law']
    if law_id is not None and str(law_id).strip() != '':
        rid = _to_int(law_id, 0)
        if rid:
            found = Law.browse(rid).exists()
            if found:
                return found
    if document_id and str(document_id).strip():
        return Law.search(
            [('rss_dok_id', '=', str(document_id).strip())], limit=1)
    return Law.browse()
